bool platform_text_ui_watch_preferences(platform_text_ui_preferences_callback callback,
                                        void *context)
{
    if (callback == NULL || context == NULL || ![NSThread isMainThread] || NSApp == nil)
        return false;
    preferences_callback = callback;
    preferences_context = context;
    VexelAppearanceWatcher *watcher = appearance_watcher();
    if (watcher == nil) {
        preferences_callback = NULL;
        preferences_context = NULL;
        return false;
    }
    if (!appearance_kvo_installed) {
        @try {
            [NSApp addObserver:watcher forKeyPath:@"effectiveAppearance"
                options:NSKeyValueObservingOptionNew context:&appearance_kvo_context];
            appearance_kvo_installed = true;
        } @catch (NSException *exception) {
            (void)exception;
        }
    }
    if (accessibility_options_observer == nil) {
        accessibility_options_observer = [NSWorkspace.sharedWorkspace.notificationCenter
            addObserverForName:NSWorkspaceAccessibilityDisplayOptionsDidChangeNotification
            object:nil queue:NSOperationQueue.mainQueue usingBlock:^(NSNotification *note) {
                (void)note;
                [watcher_view notifyPreferences];
            }];
    }
    if (system_colors_observer == nil) {
        system_colors_observer = [NSWorkspace.sharedWorkspace.notificationCenter
            addObserverForName:NSSystemColorsDidChangeNotification object:nil
            queue:NSOperationQueue.mainQueue usingBlock:^(NSNotification *note) {
                (void)note;
                [watcher_view notifyPreferences];
            }];
    }
    if (user_defaults_observer == nil) {
        user_defaults_observer = [NSNotificationCenter.defaultCenter
            addObserverForName:NSUserDefaultsDidChangeNotification object:nil
            queue:NSOperationQueue.mainQueue usingBlock:^(NSNotification *note) {
                (void)note;
                [watcher_view notifyPreferences];
            }];
    }
    [watcher notifyPreferences];
    return true;
}

void platform_text_ui_unwatch_preferences(void *context)
{
    if (![NSThread isMainThread] || context == NULL || preferences_context != context)
        return;
    watcher_view.callback = NULL;
    watcher_view.callbackContext = NULL;
    if (appearance_kvo_installed) {
        @try {
            [NSApp removeObserver:watcher_view forKeyPath:@"effectiveAppearance"
                context:&appearance_kvo_context];
        } @catch (NSException *exception) {
            (void)exception;
        }
        appearance_kvo_installed = false;
    }
    if (accessibility_options_observer != nil) {
        [NSWorkspace.sharedWorkspace.notificationCenter
            removeObserver:accessibility_options_observer];
        accessibility_options_observer = nil;
    }
    if (system_colors_observer != nil) {
        [NSWorkspace.sharedWorkspace.notificationCenter removeObserver:system_colors_observer];
        system_colors_observer = nil;
    }
    if (user_defaults_observer != nil) {
        [NSNotificationCenter.defaultCenter removeObserver:user_defaults_observer];
        user_defaults_observer = nil;
    }
    [watcher_view removeFromSuperview];
    watcher_view = nil;
    preferences_callback = NULL;
    preferences_context = NULL;
}
static bool platform_metal_dimensions_valid(uint32_t width, uint32_t height,
                                            size_t byte_count)
{
    if (width == 0U || height == 0U || width > 4096U || height > 4096U) {
        return false;
    }
    size_t width_size = (size_t)width;
    size_t height_size = (size_t)height;
    if (width_size > SIZE_MAX / height_size) {
        return false;
    }
    size_t pixels = width_size * height_size;
    return pixels <= SIZE_MAX / 4U && pixels * 4U == byte_count;
}

static bool platform_metal_wait(id<MTLCommandBuffer> command, char *diagnostic,
                                size_t diagnostic_capacity)
{
    dispatch_semaphore_t completed = dispatch_semaphore_create(0);
    [command addCompletedHandler:^(__unused id<MTLCommandBuffer> buffer) {
        dispatch_semaphore_signal(completed);
    }];
    [command commit];
    dispatch_time_t deadline = dispatch_time(DISPATCH_TIME_NOW,
        (int64_t)(PLATFORM_METAL_TIMEOUT_SECONDS * NSEC_PER_SEC));
    if (dispatch_semaphore_wait(completed, deadline) != 0) {
        return platform_metal_fail(diagnostic, diagnostic_capacity,
                                   "Metal completion timed out after 5 seconds");
    }
